#include <stdio.h>

long count_lines(const char *path) {
    FILE *f = fopen(path, "r");
    if (f == NULL) return -1;
    long n = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') n++;
    }
    fclose(f);
    return n;
}

