#include <stdlib.h>

static long count_lines(FILE *f) {
    long n = 0;
    int c;
    while ((c = fgetc(f)) != EOF)
        if (c == '\n') n++;
    return n;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: lines FILE...\n");
        return 2;
    }
    int status = EXIT_SUCCESS;
    long total = 0;
    for (int i = 1; i < argc; i++) {
        FILE *f = fopen(argv[i], "r");
        if (f == NULL) {
            fprintf(stderr, "lines: cannot open %s\n", argv[i]);
            status = EXIT_FAILURE;
            continue;
        }
        long n = count_lines(f);
        fclose(f);
        printf("%ld %s\n", n, argv[i]);
        total += n;
    }
    printf("%ld total\n", total);
    return status;
}

