#include <string>

class Clock {
public:
    explicit Clock(int seconds) : left_(seconds < 0 ? 0 : seconds) {}
    void tick(int s = 1) {
        left_ -= s;
        if (left_ < 0) left_ = 0;
    }
    bool expired() const { return left_ == 0; }
    std::string display() const {
        int m = left_ / 60, sec = left_ % 60;
        return std::to_string(m) + ":" + (sec < 10 ? "0" : "") + std::to_string(sec);
    }

private:
    int left_;
};

