#include <deque>

class MovingAverage {
public:
    explicit MovingAverage(int n) : n_(n) {}
    void add(int value) {
        window_.push_back(value);
        sum_ += value;
        if (static_cast<int>(window_.size()) > n_) {
            sum_ -= window_.front();
            window_.pop_front();
        }
    }
    double average() const { return window_.empty() ? 0.0 : static_cast<double>(sum_) / window_.size(); }

private:
    int n_;
    std::deque<int> window_;
    long sum_ = 0;
};

