#include <algorithm>
#include <functional>
#include <queue>
#include <vector>

std::vector<int> top_k(const std::vector<int>& v, int k) {
    std::priority_queue<int, std::vector<int>, std::greater<int>> heap;
    for (int x : v) {
        heap.push(x);
        if (static_cast<int>(heap.size()) > k) heap.pop();
    }
    std::vector<int> out;
    while (!heap.empty()) {
        out.push_back(heap.top());
        heap.pop();
    }
    std::reverse(out.begin(), out.end());
    return out;
}

