#include <algorithm>
#include <functional>
#include <string>
#include <vector>

class EventBus {
public:
    int on(const std::string& event, std::function<void(const std::string&)> fn) {
        handlers_.push_back({++last_id_, event, std::move(fn)});
        return last_id_;
    }
    bool off(int id) {
        auto it = std::find_if(handlers_.begin(), handlers_.end(), [id](const Handler& h) { return h.id == id; });
        if (it == handlers_.end()) return false;
        handlers_.erase(it);
        return true;
    }
    int emit(const std::string& event, const std::string& payload) {
        int ran = 0;
        for (const auto& h : handlers_) {
            if (h.event == event) {
                h.fn(payload);
                ran++;
            }
        }
        return ran;
    }

private:
    struct Handler {
        int id;
        std::string event;
        std::function<void(const std::string&)> fn;
    };
    std::vector<Handler> handlers_;
    int last_id_ = 0;
};

