    EventBus bus;
    std::string log;
    int kills = 0;
    int a = bus.on("kill", [&](const std::string& who) { log += "A:" + who + " "; kills++; });
    int b = bus.on("kill", [&](const std::string& who) { log += "B:" + who + " "; });
    bus.on("bomb", [&](const std::string& site) { log += "bomb@" + site + " "; });
    CHECK("ids are unique", a != b);
    CHECK_EQ("two kill handlers ran", bus.emit("kill", "ropz"), 2);
    CHECK_EQ("bomb handler", bus.emit("bomb", "B"), 1);
