class Range {
public:
    Range(int start, int stop, int step = 1) : start_(start), stop_(stop), step_(step) {}

    class Iterator {
    public:
        Iterator(int v, int step) : v_(v), step_(step) {}
        int operator*() const { return v_; }
        Iterator& operator++() {
            v_ += step_;
            return *this;
        }
        bool operator==(const Iterator& o) const { return v_ == o.v_; }

    private:
        int v_, step_;
    };

    Iterator begin() const { return Iterator(start_, step_); }
    Iterator end() const {
        int n = start_ >= stop_ ? 0 : (stop_ - start_ + step_ - 1) / step_;
        return Iterator(start_ + n * step_, step_);
    }

private:
    int start_, stop_, step_;
};

