#include <chrono>
#include <format>
#include <string>
#include <string_view>

enum class Level { Debug, Info, Warn, Error };

static std::string_view level_name(Level l) {
    switch (l) {
        case Level::Debug: return "DEBUG";
        case Level::Info: return "INFO";
        case Level::Warn: return "WARN";
        case Level::Error: return "ERROR";
    }
    return "?";
}

std::string log_line(Level level, std::chrono::milliseconds uptime, std::string_view msg) {
    using namespace std::chrono;
    auto h = duration_cast<hours>(uptime);
    auto m = duration_cast<minutes>(uptime - h);
    auto s = duration_cast<seconds>(uptime - h - m);
    auto ms = uptime - h - m - s;
    return std::format("[{:02}:{:02}:{:02}.{:03}] {:<5} {}", h.count(), m.count(), s.count(), ms.count(), level_name(level), msg);
}

steps.harness:
int main() {
    using namespace std::chrono_literals;
    CHECK_EQ("warn", log_line(Level::Warn, 65250ms, "disk 91%"), std::string("[00:01:05.250] WARN  disk 91%"));
    CHECK_EQ("start", log_line(Level::Info, 0ms, "boot"), std::string("[00:00:00.000] INFO  boot"));
    CHECK_EQ("error fills 5", log_line(Level::Error, 1h + 2min + 3s + 4ms, "oom"), std::string("[01:02:03.004] ERROR oom"));
    CHECK_EQ("over a day", log_line(Level::Debug, 30h, "x"), std::string("[30:00:00.000] DEBUG x"));
}

