steps.solution:
#include <functional>
#include <vector>

using Discount = std::function<long(long)>;

Discount percent_off(int pct) {
    return [pct](long cents) { return cents - cents * pct / 100; };
}

Discount flat_off(long amount) {
    return [amount](long cents) { return cents > amount ? cents - amount : 0; };
}

struct Cart {
    std::vector<long> prices;
    Discount discount = [](long cents) { return cents; };
    long total() const;
};

long Cart::total() const {
    long sum = 0;
    for (long p : prices) sum += p;
    return discount(sum);
}

steps.harness:
int main() {
    Cart c;
    c.prices = {2700, 1000, 300};
    CHECK_EQ("no discount", c.total(), 4000L);
    c.discount = percent_off(25);
    CHECK_EQ("25% off", c.total(), 3000L);
    c.discount = flat_off(500);
    CHECK_EQ("flat 500 off", c.total(), 3500L);
    c.discount = flat_off(9999);
    CHECK_EQ("never below 0", c.total(), 0L);
    auto ten = percent_off(10), half = percent_off(50);
    CHECK("each closure keeps its own pct", ten(1000) == 900 && half(1000) == 500);
}

