#include <functional>
#include <map>
#include <memory>
#include <string>
#include <vector>

struct Weapon {
    virtual ~Weapon() = default;
    virtual int damage() const = 0;
};

class Factory {
public:
    using Creator = std::function<std::unique_ptr<Weapon>()>;
    bool add(const std::string& name, Creator make);
    std::unique_ptr<Weapon> create(const std::string& name) const;
    std::vector<std::string> names() const;

private:
    std::map<std::string, Creator> creators_;
};

bool Factory::add(const std::string& name, Creator make) {
    return creators_.emplace(name, std::move(make)).second;
}

std::unique_ptr<Weapon> Factory::create(const std::string& name) const {
    auto it = creators_.find(name);
    if (it == creators_.end()) return nullptr;
    return it->second();
}

std::vector<std::string> Factory::names() const {
    std::vector<std::string> out;
    for (const auto& [name, make] : creators_) out.push_back(name);
    return out;
}

