#include <memory>
#include <string>
#include <vector>

struct Listener {
    virtual ~Listener() = default;
    virtual void on_score(const std::string& team, int score) = 0;
};

class Scoreboard {
public:
    void subscribe(const std::shared_ptr<Listener>& l);
    int publish(const std::string& team, int score);
    std::size_t listener_count() const { return listeners_.size(); }

private:
    std::vector<std::weak_ptr<Listener>> listeners_;
};

void Scoreboard::subscribe(const std::shared_ptr<Listener>& l) {
    listeners_.push_back(l);
}

int Scoreboard::publish(const std::string& team, int score) {
    int notified = 0;
    for (auto it = listeners_.begin(); it != listeners_.end();) {
        if (auto l = it->lock()) {
            l->on_score(team, score);
            notified++;
            ++it;
        } else {
            it = listeners_.erase(it);
        }
    }
    return notified;
}

