#include <cstdio>
#include <memory>
#include <optional>
#include <string>

// FileCloser, File and open_file here
struct FileCloser {
    void operator()(std::FILE* f) const {
        if (f) std::fclose(f);
    }
};
using File = std::unique_ptr<std::FILE, FileCloser>;

File open_file(const std::string& path, const char* mode) {
    return File(std::fopen(path.c_str(), mode));
}

std::optional<std::string> first_line(const std::string& path) {
    File f = open_file(path, "r");
    if (!f) return std::nullopt;
    char buf[256];
    if (!std::fgets(buf, sizeof buf, f.get())) return std::nullopt;
    std::string line(buf);
    if (!line.empty() && line.back() == '\n') line.pop_back();
    return line;
}

steps.harness:
int main() {
    CHECK_EQ("first line", first_line("maps.txt").value_or("?"), std::string("de_dust2"));
    CHECK("missing file", !first_line("missing.txt"));
    CHECK("empty file", !first_line("empty.txt"));
    {
        File w = open_file("out.txt", "w");
        CHECK("opened for writing", w != nullptr);
        std::fputs("written\n", w.get());
    }
    CHECK_EQ("closed (and flushed) at end of scope", first_line("out.txt").value_or("?"), std::string("written"));
    CHECK_EQ("File is one pointer wide", sizeof(File), sizeof(std::FILE*));
}

