#include <optional>

enum class State { Idle, Warmup, Live, Paused, Over };
enum class Event { Start, GoLive, Pause, Resume, End };

struct Transition {
    State from;
    Event on;
    State to;
};

constexpr Transition kTable[] = {
    {State::Idle, Event::Start, State::Warmup},
    {State::Warmup, Event::GoLive, State::Live},
    {State::Live, Event::Pause, State::Paused},
    {State::Paused, Event::Resume, State::Live},
    {State::Live, Event::End, State::Over},
    {State::Paused, Event::End, State::Over},
};

std::optional<State> next(State s, Event e) {
    for (const auto& t : kTable) {
        if (t.from == s && t.on == e) return t.to;
    }
    return std::nullopt;
}

class Match {
public:
    bool handle(Event e);
    State state() const { return state_; }
    int history() const { return accepted_; }

private:
    State state_ = State::Idle;
    int accepted_ = 0;
};

bool Match::handle(Event e) {
    auto to = next(state_, e);
    if (!to) return false;
    state_ = *to;
    accepted_++;
    return true;
}

