steps.solution:
#include <vector>

long insertion_sort(std::vector<int>& v) {
    long shifts = 0;
    for (std::size_t i = 1; i < v.size(); i++) {
        int key = v[i];
        std::size_t j = i;
        while (j > 0 && v[j - 1] > key) {
            v[j] = v[j - 1];
            j--;
            shifts++;
        }
        v[j] = key;
    }
    return shifts;
}

steps.harness:
int main() {
    std::vector<int> a = {5, 2, 4, 6, 1, 3};
    long s = insertion_sort(a);
