#include <utility>
#include <vector>

int kth_smallest(std::vector<int> v, int k) {
    int lo = 0, hi = static_cast<int>(v.size()) - 1;
    while (true) {
        if (lo == hi) return v[lo];
        int mid = lo + (hi - lo) / 2;
        std::swap(v[mid], v[hi]);
        int pivot = v[hi], i = lo;
        for (int j = lo; j < hi; j++) {
            if (v[j] < pivot) std::swap(v[i++], v[j]);
        }
        std::swap(v[i], v[hi]);
        if (k == i) return v[i];
        if (k < i) hi = i - 1;
        else lo = i + 1;
    }
}

