#include <algorithm>
#include <functional>
#include <list>
#include <vector>

class IntSet {
public:
    bool insert(int key) {
        auto& b = buckets_[bucket_of(key)];
        if (std::find(b.begin(), b.end(), key) != b.end()) return false;
        b.push_back(key);
        size_++;
        // grow here when the load factor passes 0.75
        if (size_ * 4 > buckets_.size() * 3) rehash(buckets_.size() * 2);
        return true;
    }
    bool contains(int key) const {
        const auto& b = buckets_[bucket_of(key)];
        return std::find(b.begin(), b.end(), key) != b.end();
    }
    std::size_t size() const { return size_; }
    std::size_t bucket_count() const { return buckets_.size(); }

private:
    void rehash(std::size_t n) {
        std::vector<std::list<int>> old(n);
        old.swap(buckets_);
        for (auto& bucket : old)
            for (int key : bucket) buckets_[bucket_of(key)].push_back(key);
    }
    std::size_t bucket_of(int key) const { return std::hash<int>{}(key) % buckets_.size(); }
    std::vector<std::list<int>> buckets_ = std::vector<std::list<int>>(16);
    std::size_t size_ = 0;
};

