#include <functional>
#include <list>
#include <string>
#include <utility>
#include <vector>

class StrMap {
public:
    void put(const std::string& key, int value);
    const int* get(const std::string& key) const;
    bool erase(const std::string& key);
    std::size_t size() const { return size_; }

private:
    using Bucket = std::list<std::pair<std::string, int>>;
    std::size_t bucket_of(const std::string& key) const { return std::hash<std::string>{}(key) % buckets_.size(); }
    std::vector<Bucket> buckets_ = std::vector<Bucket>(64);
    std::size_t size_ = 0;
};

void StrMap::put(const std::string& key, int value) {
    auto& b = buckets_[bucket_of(key)];
    for (auto& kv : b) {
        if (kv.first == key) {
            kv.second = value;
            return;
        }
    }
    b.emplace_back(key, value);
    size_++;
}

const int* StrMap::get(const std::string& key) const {
    for (const auto& kv : buckets_[bucket_of(key)])
        if (kv.first == key) return &kv.second;
    return nullptr;
}

bool StrMap::erase(const std::string& key) {
    auto& b = buckets_[bucket_of(key)];
    for (auto it = b.begin(); it != b.end(); ++it) {
        if (it->first == key) {
            b.erase(it);
            size_--;
            return true;
        }
    }
    return false;
}

