#include <functional>
#include <string>
#include <unordered_set>

struct Point {
    int x, y;
    bool operator==(const Point&) const = default;
};

// PointHash here
struct PointHash {
    std::size_t operator()(const Point& p) const {
        std::size_t h = std::hash<int>{}(p.x);
        return h ^ (std::hash<int>{}(p.y) + 0x9e3779b9 + (h << 6) + (h >> 2));
    }
};

int revisits(const std::string& moves) {
    std::unordered_set<Point, PointHash> seen{{0, 0}};
    Point p{0, 0};
    int count = 0;
    for (char m : moves) {
        if (m == 'U') p.y++;
        else if (m == 'D') p.y--;
        else if (m == 'L') p.x--;
        else if (m == 'R') p.x++;
        if (!seen.insert(p).second) count++;
    }
    return count;
}

