#include <list>
#include <optional>
#include <unordered_map>
#include <utility>

class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {}
    std::optional<int> get(int key);
    void put(int key, int value);
    std::size_t size() const { return items_.size(); }

private:
    std::size_t capacity_;
    std::list<std::pair<int, int>> items_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> where_;
};

std::optional<int> LruCache::get(int key) {
    auto it = where_.find(key);
    if (it == where_.end()) return std::nullopt;
    items_.splice(items_.begin(), items_, it->second);
    return it->second->second;
}

void LruCache::put(int key, int value) {
    auto it = where_.find(key);
    if (it != where_.end()) {
        it->second->second = value;
        items_.splice(items_.begin(), items_, it->second);
        return;
    }
    items_.emplace_front(key, value);
    where_[key] = items_.begin();
    if (items_.size() > capacity_) {
        where_.erase(items_.back().first);
        items_.pop_back();
    }
}

