#include <utility>
#include <vector>

class MinHeap {
public:
    void push(int v);
    void pop();
    int top() const;
    bool empty() const { return a_.empty(); }
    std::size_t size() const { return a_.size(); }

private:
    std::vector<int> a_;
};

void MinHeap::push(int v) {
    a_.push_back(v);
    std::size_t i = a_.size() - 1;
    while (i > 0) {
        std::size_t parent = (i - 1) / 2;
        if (a_[parent] <= a_[i]) break;
        std::swap(a_[parent], a_[i]);
        i = parent;
    }
}

void MinHeap::pop() {
    a_[0] = a_.back();
    a_.pop_back();
    std::size_t i = 0, n = a_.size();
    while (true) {
        std::size_t l = 2 * i + 1, r = 2 * i + 2, smallest = i;
        if (l < n && a_[l] < a_[smallest]) smallest = l;
        if (r < n && a_[r] < a_[smallest]) smallest = r;
        if (smallest == i) break;
        std::swap(a_[i], a_[smallest]);
        i = smallest;
    }
}

int MinHeap::top() const { return a_[0]; }

