using Graph = std::vector<std::vector<int>>;

Graph build(int n, const std::vector<std::pair<int, int>>& edges, bool directed) {
    Graph adj(n);
    for (auto [a, b] : edges) {
        adj[a].push_back(b);
        if (!directed) adj[b].push_back(a);
    }
    return adj;
}

int max_degree(const Graph& adj) {
    std::size_t best = 0;
    for (const auto& nb : adj)
        if (nb.size() > best) best = nb.size();
    return static_cast<int>(best);
}

