#include <functional>
#include <queue>
#include <utility>
#include <vector>

struct Edge {
    int from, to;
    long long cost;
};

std::vector<long long> dijkstra(int n, const std::vector<Edge>& edges, int src) {
    std::vector<std::vector<std::pair<int, long long>>> adj(n);
    for (const auto& e : edges) adj[e.from].push_back({e.to, e.cost});
    const long long INF = -1;
    std::vector<long long> dist(n, INF);
    using Item = std::pair<long long, int>;
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> heap;
    dist[src] = 0;
    heap.push({0, src});
    while (!heap.empty()) {
        auto [d, v] = heap.top();
        heap.pop();
        if (d > dist[v]) continue;
        for (auto [w, cost] : adj[v]) {
            long long nd = d + cost;
            if (dist[w] == INF || nd < dist[w]) {
                dist[w] = nd;
                heap.push({nd, w});
            }
        }
    }
    return dist;
}

