#include <numeric>
#include <utility>
#include <vector>

class UnionFind {
public:
    explicit UnionFind(int n);
    int find(int x);
    bool unite(int a, int b);
    int groups() const;
    int size_of(int x);

private:
    std::vector<int> parent_, size_;
    int groups_;
};

UnionFind::UnionFind(int n) : parent_(n), size_(n, 1), groups_(n) {
    std::iota(parent_.begin(), parent_.end(), 0);
}

int UnionFind::find(int x) {
    int root = x;
    while (parent_[root] != root) root = parent_[root];
    while (parent_[x] != root) {
        int next = parent_[x];
        parent_[x] = root;
        x = next;
    }
    return root;
}

bool UnionFind::unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return false;
    if (size_[a] < size_[b]) std::swap(a, b);
    parent_[b] = a;
    size_[a] += size_[b];
    groups_--;
    return true;
}

int UnionFind::groups() const { return groups_; }

int UnionFind::size_of(int x) { return size_[find(x)]; }

