#include <string>
#include <vector>

// Removes banned players, then appends one substitute per removal.
void apply_bans(std::vector<std::string>& roster, const std::set<std::string>& banned, const std::string& sub) {
    std::size_t removed = std::erase_if(roster, [&](const std::string& p) { return banned.count(p) > 0; });
    for (std::size_t i = 0; i < removed; i++) roster.push_back(sub);
}

// Returns the first player's name after adding a new player at the end.
std::string captain_after_signing(std::vector<std::string>& roster, const std::string& signing) {
    std::string captain = roster.front();
    roster.push_back(signing);
    return captain;
}

