template <typename T>
class Vec {
public:
    Vec() = default;
    ~Vec() { delete[] data_; }
    Vec(const Vec& other) : data_(other.size_ ? new T[other.size_] : nullptr), size_(other.size_), cap_(other.size_) {
        for (std::size_t i = 0; i < size_; i++) data_[i] = other.data_[i];
    }
    Vec& operator=(Vec other) {
        swap(other);
        return *this;
    }
    void swap(Vec& o) noexcept {
        std::swap(data_, o.data_);
        std::swap(size_, o.size_);
        std::swap(cap_, o.cap_);
