    std::string name() {
        skip();
        std::string n;
        while (i < s.size() && is_name_char(s[i])) n += s[i++];
        return n;
    }
    long long number() {
        skip();
        long long v = 0;
        while (i < s.size() && s[i] >= '0' && s[i] <= '9') v = v * 10 + (s[i++] - '0');
        return v;
    }
