        if (eat('-')) return -factor();
        if (eat('(')) {
            long long v = expr();
            eat(')');
            return v;
        }
        skip();
        if (i < s.size() && is_name_char(s[i])) return vars[name()];
        return number();
    }
    long long term() {
        long long v = factor();
        for (;;) {
            if (eat('*')) v *= factor();
            else if (eat('/')) v /= factor();
            else return v;
        }
    }
    long long expr() {
        long long v = term();
        for (;;) {
            if (eat('+')) v += term();
            else if (eat('-')) v -= term();
            else return v;
        }
    }
};

