static _Alignas(16) unsigned char heap[4096];
static size_t used = 0;

void *bump_alloc(size_t n) {
    if (n == 0) return NULL;
    size_t rounded = (n + 7) & ~(size_t)7;
    if (rounded > sizeof(heap) - used) return NULL;
    void *p = heap + used;
    used += rounded;
    return p;
}

void bump_reset(void) {
    used = 0;
}

#define BLOCK 16
#define BLOCKS 32
static _Alignas(16) unsigned char pool[BLOCK * BLOCKS];
static void *free_list = NULL;

void pool_init(void) {
    for (int i = 0; i < BLOCKS; i++) {
        void **block = (void **)(pool + i * BLOCK);
        *block = (i + 1 < BLOCKS) ? (void *)(pool + (i + 1) * BLOCK) : NULL;
    }
    free_list = pool;
}

void *pool_alloc(void) {
    if (free_list == NULL) return NULL;
    void *p = free_list;
    free_list = *(void **)p;
    return p;
}

void pool_free(void *p) {
    *(void **)p = free_list;
    free_list = p;
}

milestones.harness:
int main(void) {
    pool_init();
    char *a = pool_alloc();
    char *b = pool_alloc();
    CHECK("first block is the pool start", a != NULL && b == a + 16);
    int n = 2;
    while (pool_alloc() != NULL) n++;
    CHECK_INT("exactly 32 blocks", n, 32);
    pool_free(b);
    CHECK("freed block is reused first", pool_alloc() == b);
    CHECK("empty again", pool_alloc() == NULL);
    pool_free(a);
    pool_free(b);
    CHECK("LIFO order", pool_alloc() == b && pool_alloc() == a);
    pool_init();
    int *x = pool_alloc();
    x[0] = 1; x[1] = 2; x[2] = 3; x[3] = 4;
    int *y = pool_alloc();
    y[0] = 9;
    CHECK("blocks don't overlap", x[3] == 4 && y[0] == 9);
    return 0;
}

