exercise.solution:
void rotate_left(int a[], int n) {
    if (n < 2) return;
    int first = a[0];
    for (int i = 0; i < n - 1; i++) a[i] = a[i + 1];
    a[n - 1] = first;
}

exercise.harness:
int main(void) {
    int a[] = {1, 2, 3, 4};
    rotate_left(a, 4);
    CHECK("{1,2,3,4} -> {2,3,4,1}", a[0] == 2 && a[1] == 3 && a[2] == 4 && a[3] == 1);
    int b[] = {9};
    rotate_left(b, 1);
    CHECK("single element", b[0] == 9);
    return 0;
}

