exercise.solution:
#include <ctype.h>
#include <stdio.h>

int copy_upper(const char *src, const char *dst) {
    FILE *in = fopen(src, "r");
    if (in == NULL) return -1;
    FILE *out = fopen(dst, "w");
    if (out == NULL) {
        fclose(in);
        return -1;
    }
    int c;
    while ((c = fgetc(in)) != EOF) fputc(toupper(c), out);
    fclose(in);
    fclose(out);
    return 0;
}

exercise.harness:
int main(void) {
    CHECK_INT("copy works", copy_upper("in.txt", "out.txt"), 0);
    FILE *f = fopen("out.txt", "r");
    char buf[64] = "";
    size_t n = fread(buf, 1, sizeof buf - 1, f);
    buf[n] = '\0';
    fclose(f);
    CHECK_STR("uppercased", buf, "GG WP 2-0\nEZ\n");
    CHECK_INT("missing source", copy_upper("nope.txt", "x.txt"), -1);
    return 0;
}

