exercise.solution:
void apply(int *a, int n, int (*f)(int)) {
    for (int i = 0; i < n; i++) a[i] = f(a[i]);
}

int count_if(const int *a, int n, int (*pred)(int)) {
    int c = 0;
    for (int i = 0; i < n; i++)
        if (pred(a[i])) c++;
    return c;
}

