exercise.solution:
int digit_sum(int n) {
    int s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return s;
}

exercise.harness:
int main(void) {
    CHECK_INT("4721", digit_sum(4721), 14);
    CHECK_INT("0", digit_sum(0), 0);
    CHECK_INT("9", digit_sum(9), 9);
    CHECK_INT("1000000", digit_sum(1000000), 1);
    return 0;
}

exercise.solution:
int count_multiples(int limit, int k) {
    int c = 0;
    for (int i = 1; i <= limit; i++)
        if (i % k == 0) c++;
    return c;
}

exercise.harness:
