exercise.solution:
void min_max(const int *a, int n, int *mn, int *mx) {
    *mn = *mx = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < *mn) *mn = a[i];
        if (a[i] > *mx) *mx = a[i];
    }
}

exercise.harness:
int main(void) {
    int a[] = {3, -2, 9, 4};
    int lo = 0, hi = 0;
    min_max(a, 4, &lo, &hi);
