class Counter {
public:
    void add(int n) {
        value_ += n;
        if (value_ > max_) max_ = value_;
    }
    void reset() { value_ = 0; }
    int value() const { return value_; }
    int max_seen() const { return max_; }

private:
    int value_ = 0;
    int max_ = 0;
};

exercise.harness:
int main() {
    Counter c;
    c.add(5);
    c.add(3);
    CHECK_EQ("value 8", c.value(), 8);
    c.reset();
    c.add(2);
    CHECK_EQ("value after reset", c.value(), 2);
    CHECK_EQ("max survives reset", c.max_seen(), 8);
    const Counter& r = c;
    CHECK_EQ("const access", r.value(), 2);
}

